SIGNATURES = [
    ([0x89, 0x50, 0x4E, 0x47], "png"),
    ([0xFF, 0xD8, 0xFF], "jpeg"),
    ([0x25, 0x50, 0x44, 0x46], "pdf"),
    ([0x50, 0x4B, 0x03, 0x04], "zip"),
    ([0x4D, 0x5A], "exe"),
    ([0x7F, 0x45, 0x4C, 0x46], "elf"),
]

def file_type(data):
    for magic, name in SIGNATURES:
        if data[:len(magic)] == magic:
            return name
    return "unknown"

unitTests:
@test("known formats")
def _():
    check_eq(file_type([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]), "png")
    check_eq(file_type([0xFF, 0xD8, 0xFF, 0xE0]), "jpeg")
    check_eq(file_type(list(b"%PDF-1.7")), "pdf")
    check_eq(file_type(list(b"PK\x03\x04rest")), "zip")
    check_eq(file_type(list(b"MZ\x90\x00")), "exe")
    check_eq(file_type([0x7F, 0x45, 0x4C, 0x46, 2]), "elf")

@test("unknown and short")
def _():
    check_eq(file_type(list(b"Hello")), "unknown")
    check_eq(file_type([0x89, 0x50]), "unknown")
    check_eq(file_type([]), "unknown")

